describe('Payment Card Decline Error Handling', () => {
    beforeEach(() => {
        cy.visit('/payment'); // Adjust the URL to your payment page
    });

    it('should display an error message when the payment card is declined (happy path)', () => {
        cy.get('input[name="cardNumber"]').type('4000 0000 0000 0002'); // Example declined card number
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvv"]').type('123');
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('be.visible')
            .and('contain', 'Your payment was declined. Please check your card details or use a different card.');
    });

    it('should not display an error message when the payment is successful (edge case)', () => {
        cy.get('input[name="cardNumber"]').type('4242 4242 4242 4242'); // Example successful card number
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvv"]').type('123');
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('not.exist');
        cy.get('.success-message').should('be.visible')
            .and('contain', 'Payment successful! Thank you for your purchase.');
    });
});
